require('./chapter2.js');
const assert=require('node:assert/strict');
const {Game,DashInput,CONTENT,OPENING,prologueHand,openingLine,openingFrame,CFG,BOSS,SWEETS,WANDS,poseFor,canvasPoint,controlsFor,aimFor,overlap}=require('./engine.js');
let passed=0;function test(name,fn){fn();passed++;console.log('PASS '+name);}
function tick(g,s,input={}){for(let n=0;n<Math.round(s*120);n++)g.step(1/120,input);}
function settle(g){for(let i=0;i<400&&g.state==='transition';i++)g.step(1/120);assert.notEqual(g.state,'transition');}
function empty(seed=1){const g=new Game(seed,{story:false});g.enemies=[];g.sweets=[];g.drops=[];g.events=[];return g;}
test('Every new run starts with 2 hearts, one standard wand and zero happiness',()=>{const g=new Game(13);assert.deepEqual([g.life,g.maxLife,g.happiness,g.inventory],[2,2,0,['star']]);});
test('Stage layouts, enemies and pickups stay fixed across different play seeds',()=>{const a=new Game(13),b=new Game(13),c=new Game(14);assert.deepEqual(a.platforms,b.platforms);assert.deepEqual(a.platforms,c.platforms);assert.deepEqual(a.drops,c.drops);assert.deepEqual(a.enemies,c.enemies);assert.deepEqual(a.drops,b.drops);});
test('A full-life player caps happiness at 99 and does not heal on damage',()=>{const g=empty();g.happiness=98;g.collectSweet(g.sweet(0,0,'cake',null));assert.equal(g.happiness,99);g.player.inv=0;g.hurt(200);assert.equal(g.life,1);assert.equal(g.happiness,99);tick(g,2);assert.equal(g.life,1);g.collectSweet(g.sweet(0,0,'candy',null));assert.equal(g.life,2);assert.equal(g.happiness,0);});
test('Recovery consumes the whole gauge and restores exactly one heart',()=>{const g=empty();g.maxLife=4;g.life=1;g.happiness=95;g.collectSweet(g.sweet(0,0,'cake',null));assert.equal(g.life,2);assert.equal(g.happiness,0);});
test('Zero HP transforms, does not defeat; 5-second expiry restores full HP',()=>{const g=empty();const e=g.spawnEnemy('slime',600,458);e.hp=0;g.transform(e,'star');assert.equal(e.state,'candy');assert.equal(g.defeated,0);tick(g,4.9);assert.equal(e.state,'candy');tick(g,.12);assert.equal(e.state,'alive');assert.equal(e.hp,e.maxHp);assert.equal(g.sweets.length,0);});
test('Candy contact immediately confirms a kill and cannot double-count it',()=>{const g=empty();const e=g.spawnEnemy('slime',g.player.x,458);g.transform(e,'star');g.step(1/120);assert.equal(e.state,'dead');assert.equal(g.defeated,1);assert.equal(g.eaten,1);g.collectSweet(e.sweet);assert.equal(g.eaten,1);});
test('Paused games freeze candy expiry and all gameplay time',()=>{const g=empty();const e=g.spawnEnemy('bat',600,458);g.transform(e,'star');g.state='paused';tick(g,20);assert.equal(e.candyTime,5);assert.equal(g.time,0);});
test('Damage never drops a wand; invulnerability rejects repeat damage',()=>{const g=empty();g.inventory.push('comet');g.player.inv=0;g.hurt(200);assert.equal(g.life,1);assert.deepEqual(g.inventory,['star','comet']);g.hurt(200);assert.equal(g.life,1);tick(g,1.6);g.hurt(200);assert.equal(g.state,'lost');});
test('Second wand is acquired; a third requires a selected swap and remains on ground',()=>{const g=empty();const drop=wand=>({id:1,type:'wand',wand,x:g.player.x,y:428,w:26,h:30,cooldown:0});g.drops=[drop('spread')];g.interact();assert.deepEqual(g.inventory,['star','spread']);assert.equal(g.drops.length,0);g.drops=[drop('sugar')];g.interact();assert.equal(g.state,'swap');assert.deepEqual(g.inventory,['star','spread']);g.swap(0);assert.deepEqual(g.inventory,['sugar','spread']);assert.equal(g.drops[0].wand,'star');assert.equal(g.state,'playing');tick(g,.7);g.interact();g.swap(0);assert.equal(g.inventory[0],'star');assert.equal(g.drops[0].wand,'sugar');});
test('A cancelled swap preserves both inventory and ground wand',()=>{const g=empty();g.inventory=['star','spread'];g.drops=[{type:'wand',wand:'comet',x:g.player.x,y:428,cooldown:0}];g.interact();g.swap(null);assert.deepEqual(g.inventory,['star','spread']);assert.equal(g.drops[0].wand,'comet');});
test('Door transition retains life, capacity, happiness, energy and equipment',()=>{const g=empty();g.life=1;g.maxLife=3;g.happiness=79;g.energy=37;g.inventory=['spread','sugar'];g.player.x=g.exit.x;g.enterDoor();settle(g);assert.equal(g.stage,1);assert.deepEqual([g.life,g.maxLife,g.happiness,g.energy,g.inventory],[1,3,79,37,['spread','sugar']]);});
test('Heart upgrade fills each added heart and respects the cap',()=>{const g=empty();for(let i=0;i<5;i++){g.drops=[{type:'heart',x:g.player.x,y:428,cooldown:0}];g.interact();}assert.equal(g.maxLife,4);assert.equal(g.life,4);});
test('Sugar wand only yields medium or large candy ranks',()=>{const g=empty();for(let i=0;i<100;i++){const e=g.spawnEnemy('slime',600,458);g.transform(e,'sugar');assert.ok(SWEETS[e.sweet.kind].rank>=1);}});
test('Projectiles damage enemies and create candy through normal combat',()=>{const g=empty();g.player.x=200;const e=g.spawnEnemy('slime',330,458);tick(g,1.2,{fire:true});assert.equal(e.state,'candy');assert.equal(g.defeated,0);});
test('Jump clears the first platform height; releasing early produces a shorter jump',()=>{const full=empty(),short=empty();for(const g of [full,short]){g.player.x=100;g.platforms=[{x:0,y:458,w:4000,h:100,ground:true}];g.step(1/120,{jump:true,jumpHeld:true});}let y1=999,y2=999;for(let n=0;n<100;n++){full.step(1/120,{jumpHeld:true});short.step(1/120,{jumpHeld:false});y1=Math.min(y1,full.player.y);y2=Math.min(y2,short.player.y);}assert.ok(402-y1>95);assert.ok(y2>y1+20);});
test('300 seeded stages all retain a complete safe floor and reachable ascending steps',()=>{for(let seed=0;seed<100;seed++){const g=new Game(seed);for(let st=0;st<3;st++){g.stage=st;g.loadStage();const floor=g.platforms.find(p=>p.ground);assert.equal(floor.x,0);assert.equal(floor.w,g.worldWidth);for(const p of g.platforms.filter(p=>!p.ground)){assert.ok(p.x>=0&&p.x+p.w<=g.worldWidth);if(458-p.y>100)assert.ok(g.platforms.some(q=>q.y>p.y&&q.y-p.y<100&&Math.max(0,p.x-(q.x+q.w),q.x-(p.x+p.w))<120),'unreachable upper step');}}}});
test('Boss HP zero is not a win; eating is the win condition',()=>{const g=empty();g.stage=2;g.loadStage();const e=g.enemies.find(e=>e.type==='boss');g.transform(e,'star');assert.equal(g.state,'playing');tick(g,BOSS.hitStop+.01);g.collectSweet(e.sweet);if(g.state==='celebrating')tick(g,3.2);assert.equal(g.state,'won');assert.equal(g.defeated,1);});
test('A fresh run resets all growth and gear after defeat',()=>{const g=empty();g.maxLife=4;g.happiness=99;g.inventory=['sugar','comet'];g.state='lost';g.reset(44);assert.deepEqual([g.life,g.maxLife,g.happiness,g.inventory,g.stage,g.state],[2,2,0,['star'],0,'playing']);});
test('A fresh run starts with full magic energy',()=>{assert.equal(empty().energy,100);});
test('Each wand charges once per cast, including the three-projectile wand',()=>{for(const key of Object.keys(WANDS)){const g=empty();g.inventory=[key];assert.equal(g.shoot(),true);assert.equal(g.energy,100-WANDS[key].cost);assert.equal(g.bullets.length,key==='spread'?3:1);const before=g.energy;assert.equal(g.shoot(),false);assert.equal(g.energy,before);}});
test('Insufficient energy emits no projectile and cannot become negative',()=>{const g=empty();g.energy=5;assert.equal(g.shoot(),false);assert.equal(g.bullets.length,0);assert.equal(g.energy,5);g.energy=6;assert.equal(g.shoot(),true);assert.equal(g.energy,0);});
test('Energy regenerates with game time, clamps to 100, and freezes in pause',()=>{const g=empty();g.energy=0;tick(g,2);assert.ok(Math.abs(g.energy-36)<1e-6);g.state='paused';tick(g,5);assert.ok(Math.abs(g.energy-36)<1e-6);g.state='playing';tick(g,10);assert.equal(g.energy,100);});
test('Sustained fire depletes energy and releasing fire restores it',()=>{const g=empty();tick(g,12,{fire:true});assert.ok(g.energy<10);tick(g,6);assert.equal(g.energy,100);});
test('E never opens a door; door interaction only works in front of a grounded door',()=>{const g=empty();assert.equal(g.enterDoor(),false);g.player.x=g.exit.x;g.interact();assert.equal(g.stage,0);g.player.grounded=false;assert.equal(g.enterDoor(),false);g.player.grounded=true;g.player.y=250;assert.equal(g.enterDoor(),false);g.player.y=CFG.ground-g.player.h;assert.equal(g.enterDoor(),true);settle(g);assert.equal(g.stage,1);});
test('Standing fire keeps the stationary lower-body pose throughout every shot',()=>{const g=empty();g.shoot();for(let i=0;i<50;i++){g.step(1/120,{fire:true});const pose=poseFor(g.player);assert.equal(pose.base,0);if(g.player.attack>0){assert.equal(pose.upper,1);assert.equal(pose.split,true);}}});
test('Moving fire preserves the same walk phase and legs as movement without fire',()=>{const a=empty(),b=empty();for(let n=0;n<120;n++){a.step(1/120,{right:true});b.step(1/120,{right:true,fire:true});assert.equal(a.player.walkPhase,b.player.walkPhase);assert.equal(poseFor(a.player).base,poseFor(b.player).base);}assert.ok(a.player.walkPhase>0);});
test('Walking against a wall does not cycle the legs without movement',()=>{const g=empty();g.player.x=0;tick(g,1,{left:true});assert.equal(g.player.walkPhase,0);});
test('W and Up jump at a door without entering; Space enters once without jumping on arrival',()=>{for(const key of ['KeyW','ArrowUp']){const g=empty();g.player.x=g.exit.x;g.step(1/120,controlsFor(new Set([key]),new Set([key]),g.canEnterDoor()));assert.equal(g.stage,0);assert.ok(g.player.vy<0);}const g=empty();g.player.x=g.exit.x;g.step(1/120,controlsFor(new Set(['Space']),new Set(['Space']),true));settle(g);assert.equal(g.stage,1);assert.equal(g.player.vy,0);for(let i=0;i<60;i++)g.step(1/120,controlsFor(new Set(['Space']),new Set(),g.canEnterDoor()));assert.equal(g.stage,1);assert.equal(g.player.grounded,true);});
test('Space away from the door still jumps, and short Up presses produce short jumps',()=>{const g=empty();g.step(1/120,controlsFor(new Set(['Space']),new Set(['Space']),false));assert.ok(g.player.vy<0);const a=empty(),b=empty();for(const e of [a,b])e.step(1/120,controlsFor(new Set(['ArrowUp']),new Set(['ArrowUp'])));for(let i=0;i<24;i++){a.step(1/120,controlsFor(new Set(['ArrowUp']),new Set()));b.step(1/120,controlsFor(new Set(),new Set()));}assert.ok(b.player.y>a.player.y+20);});
test('Mouse coordinates remain correct with CSS scaling, offsets and letterboxing',()=>{assert.deepEqual(canvasPoint(340,235,{left:100,top:100,width:480,height:270}),{x:480,y:270,inside:true});assert.deepEqual(canvasPoint(250,350,{left:10,top:80,width:480,height:540}),{x:480,y:270,inside:true});assert.equal(canvasPoint(250,90,{left:10,top:80,width:480,height:540}).inside,false);assert.equal(canvasPoint(0,0,{left:0,top:0,width:0,height:0}),null);});
test('All eight aiming directions fire toward the target with the correct speed and cost',()=>{for(let n=0;n<8;n++){const g=empty(),p=g.player,angle=n*Math.PI/4;const tx=p.x+p.w/2+36+Math.cos(angle)*250,ty=p.y+3+Math.sin(angle)*250;g.step(1/120,{aimX:tx,aimY:ty,fire:true});const b=g.bullets[0];assert.ok(Math.abs(Math.atan2(Math.sin(Math.atan2(b.vy,b.vx)-angle),Math.cos(Math.atan2(b.vy,b.vx)-angle)))<1e-8);assert.ok(Math.abs(Math.hypot(b.vx,b.vy)-WANDS.star.speed)<1e-8);assert.equal(g.energy,94);}});
test('Spread rotates as a three-shot fan around the cursor direction',()=>{const g=empty();g.inventory=['spread'];const p=g.player;g.step(1/120,{aimX:p.x+p.w/2+36,aimY:100,fire:true});assert.equal(g.bullets.length,3);assert.equal(g.energy,86);g.bullets.forEach((b,i)=>assert.ok(Math.abs(Math.atan2(b.vy,b.vx)-(-Math.PI/2+(i-1)*.19))<1e-8));});
test('Movement controls the body direction while bullets independently track the cursor',()=>{const g=empty();g.step(1/120,{left:true,aimX:600,aimY:429,fire:true});assert.ok(g.player.vx<0);assert.equal(g.player.facing,-1);assert.ok(g.bullets[0].vx>0);g.player.fire=0;g.step(1/120,{left:true,fire:true});assert.equal(g.player.facing,-1);assert.ok(g.bullets.at(-1).vx<0);});
test('An upward aimed shot can hit a flying enemy through normal combat',()=>{const g=empty(),p=g.player,e=g.spawnEnemy('bat',p.x+12,400);e.hp=1;for(let i=0;i<96&&e.state==='alive';i++)g.step(1/120,{aimX:e.x+16,aimY:e.y+14,fire:true});assert.equal(e.state,'candy');});
function arena(){const g=new Game(123,{story:false});g.stage=2;g.loadStage();g.enemies=g.enemies.filter(e=>e.type==='boss');g.sweets=[];g.drops=[];g.player.inv=0;g.player.x=g.arenaStart+400;g.bossAwake=true;g.arenaLocked=true;return g;}
test('Boss arena leaves retreat room at activation and clear floor on both sides',()=>{const g=arena();assert.equal(g.worldWidth-g.arenaStart,1200);g.bossAwake=false;g.arenaLocked=false;g.player.x=g.arenaStart+321;g.step(1/120);assert.equal(g.bossAwake,true);tick(g,1,{left:true});assert.ok(g.player.x<g.arenaStart+110);assert.equal(g.life,2);assert.ok(g.platforms.filter(p=>!p.ground).every(p=>p.x+p.w<g.arenaStart));const b=g.enemies[0];assert.ok(b.x-g.arenaStart>300);assert.ok(g.worldWidth-b.x-b.w>250);});
test('A held jump clears the boss from both sides over a useful range of takeoff distances',()=>{for(const dir of [-1,1])for(const distance of [60,70,80,90,100]){const g=arena(),b=g.enemies[0];b.phaseTime=10;g.player.x=dir>0?b.x-distance:b.x+b.w+distance-g.player.w;let crossed=false;for(let i=0;i<120;i++){g.step(1/120,{left:dir<0,right:dir>0,jump:i===0,jumpHeld:true});if(dir>0?g.player.x>b.x+b.w:g.player.x+g.player.w<b.x)crossed=true;}assert.equal(g.life,2,'body jump direction '+dir+', distance '+distance);assert.ok(crossed);}});
test('Boss attacks without warnings, applies more pressure below half health, and keeps a recovery gap',()=>{for(const enraged of [false,true]){const g=arena(),b=g.enemies[0];g.player.x=g.arenaStart+180;g.player.inv=100;if(enraged)b.hp=b.maxHp/2;let waves=0,dashes=0,elapsedRecovery=0,lastRecovery=0;for(let i=0;i<120*15;i++){const prev=b.phase,shots=g.events.filter(e=>e.type==='enemyShoot').length;g.step(1/120);assert.equal(b.telegraph,0);assert.notEqual(b.phase,'windup');if(prev==='recover')elapsedRecovery+=1/120;if(b.phase==='recover'&&prev!=='recover')elapsedRecovery=0;if(g.events.filter(e=>e.type==='enemyShoot').length>shots){waves++;elapsedRecovery=0;}if(b.phase==='dash'&&prev!=='dash'){dashes++;lastRecovery=elapsedRecovery;assert.ok(lastRecovery>=(enraged?.79:1.09));assert.ok(lastRecovery<(enraged?.85:1.15));}}assert.ok(waves>=4&&dashes>=4);}});
test('The low boss wave is dangerous on the ground and avoidable with a normal jump',()=>{for(const jump of [false,true]){const g=arena(),b=g.enemies[0];g.player.x=b.x-190;b.phase='rest';b.phaseTime=.01;b.nextMove='wave';let started=false;for(let n=0;n<130;n++){const approaching=g.hostile.some(s=>s.vx<0&&s.x-g.player.x<100&&s.x>g.player.x);const begin=jump&&!started&&approaching;if(begin)started=true;g.step(1/120,{jump:begin,jumpHeld:true});}assert.equal(g.life,jump?2:1);}});
test('The grounded rush can be jumped without contact damage',()=>{const g=arena(),b=g.enemies[0];g.player.x=b.x-120;b.phase='dash';b.phaseTime=BOSS.dashSeconds;b.chargeDir=-1;for(let n=0;n<100;n++)g.step(1/120,{right:true,jump:n===0,jumpHeld:true});assert.equal(g.life,2);assert.ok(g.player.x>b.x+b.w);});
test('Initial wand and two hearts can defeat and eat the boss using aim, retreat and timed jumps',()=>{const g=arena(),b=g.enemies[0];let jumps=0;for(let n=0;n<120*35&&g.state==='playing';n++){const p=g.player,dx=b.x+b.w/2-p.x-p.w/2,threat=g.hostile.some(s=>s.vx*(p.x-s.x)>0&&Math.abs(s.x-p.x)<100&&Math.abs(s.y-CFG.ground)<25),jump=p.grounded&&threat,sweet=b.state==='candy';if(jump)jumps++;g.step(1/120,{jump,jumpHeld:true,fire:!sweet,aimX:b.x+b.w/2,aimY:b.y+b.h/2,left:!sweet&&dx>0&&dx<320,right:sweet&&dx>10});}if(g.state==='celebrating')tick(g,3.2);assert.equal(g.state,'won');assert.ok(g.life>=1);assert.ok(jumps>0);assert.equal(g.defeated,1);assert.deepEqual(g.inventory,['star']);});
test('A timed-out boss sweet revives into a fresh rest phase, not an instant attack',()=>{const g=arena(),b=g.enemies[0];b.phase='dash';b.phaseTime=.01;g.transform(b,'star');tick(g,5.02+BOSS.hitStop);assert.equal(b.state,'alive');assert.equal(b.phase,'rest');assert.ok(b.phaseTime>1.2);assert.equal(b.hp,b.maxHp);});

test('Boss fan has five evenly spaced upward directions at the same speed',()=>{const g=arena(),b=g.enemies[0];b.phaseTime=0;g.stepBoss(b,0);assert.equal(g.hostile.length,5);g.hostile.forEach((shot,i)=>{const a=-Math.PI+i*Math.PI/4;assert.ok(Math.abs(shot.vx-Math.cos(a)*BOSS.waveSpeed)<1e-8);assert.ok(Math.abs(shot.vy-Math.sin(a)*BOSS.waveSpeed)<1e-8);assert.ok(shot.vy<=1e-8);});});
test('All 300 stages distribute grounded enemies on retained platforms',()=>{for(let seed=0;seed<100;seed++)for(let stage=0;stage<3;stage++){const g=new Game(seed);g.stage=stage;g.loadStage();const upper=g.enemies.filter(e=>e.platform);assert.ok(upper.length>=(stage===2?2:5));assert.ok(upper.some(e=>e.type==='sprout'));assert.ok(upper.some(e=>e.type==='slime'));for(const e of upper){assert.ok(g.platforms.includes(e.platform));assert.equal(e.y+e.h,e.platform.y);assert.ok(e.x>=e.platform.x&&e.x+e.w<=e.platform.x+e.platform.w);}}});
test('Platform slimes patrol without falling, including after candy revival',()=>{const g=new Game(13);g.player.x=0;const e=g.enemies.find(e=>e.platform&&e.type==='slime');g.enemies=[e];g.sweets=[];tick(g,15);assert.equal(e.y+e.h,e.platform.y);assert.ok(e.x>=e.patrolLeft&&e.x<=e.patrolRight);g.transform(e,'star');tick(g,5.1);assert.equal(e.state,'alive');tick(g,10);assert.equal(e.y+e.h,e.platform.y);assert.ok(e.x>=e.patrolLeft&&e.x<=e.patrolRight);});
test('Elevated sprouts launch aimed attacks at a player on a platform',()=>{const g=new Game(13),e=g.enemies.find(e=>e.platform&&e.type==='sprout');g.enemies=[e];g.sweets=[];g.player.x=e.x+120;g.player.y=e.platform.y-g.player.h;g.player.grounded=true;e.attack=0;g.step(1/120);assert.equal(g.hostile.length,1);assert.ok(g.hostile[0].y<CFG.ground-70);assert.ok(g.hostile[0].vx>0);assert.ok(g.hostile[0].vy<0);});

test('Chapter 1 retains three single-area stages alongside Chapter 2',()=>{assert.equal(CONTENT.plannedChapters,12);assert.deepEqual(CONTENT.chapters.map(c=>c.id),[0,1,2]);assert.deepEqual(CONTENT.chapters[1].stages.map(s=>s.areas.length),[1,1,1]);const g=empty();assert.deepEqual(g.location,{chapter:1,stage:1,area:1});g.player.x=g.exit.x;g.enterDoor();settle(g);assert.deepEqual(g.location,{chapter:1,stage:2,area:1});});
test('Terrain and item placement do not depend on previous combat randomness',()=>{const a=empty(1),b=empty(993);for(let i=0;i<400;i++)b.rng();a.stage=b.stage=1;a.loadStage();b.loadStage();assert.deepEqual(a.platforms,b.platforms);assert.deepEqual(a.drops,b.drops);assert.deepEqual(a.enemies,b.enemies);});
test('A directional double tap starts running only on the second distinct press',()=>{for(const dir of [-1,1]){const d=new DashInput();d.press(dir,1);assert.equal(d.active,0);d.press(dir,1.1);assert.equal(d.active,0);d.release(dir);d.press(dir,1.2);assert.equal(d.active,dir);d.release(dir);assert.equal(d.active,0);}});
test('Slow taps, alternating directions, opposed inputs and clears never leave a dash latched',()=>{const d=new DashInput();d.press(1,0);d.release(1);d.press(1,.4);assert.equal(d.active,0);d.release(1);d.press(-1,.5);assert.equal(d.active,0);d.release(-1);d.press(-1,.6);assert.equal(d.active,-1);d.press(1,.65);assert.equal(d.active,0);d.clear();d.press(1,.7);assert.equal(d.active,0);});
test('Keyboard direction aliases produce the same dash input and opposed keys cancel movement',()=>{for(const [key,dir]of [['KeyA',-1],['ArrowLeft',-1],['KeyD',1],['ArrowRight',1]]){assert.equal(controlsFor(new Set([key]),new Set(),false,dir).dash,true);assert.equal(controlsFor(new Set([key]),new Set(),false,-dir).dash,false);}assert.equal(controlsFor(new Set(['KeyA','KeyD']),new Set(),false,1).dash,false);});
test('Dash is faster in both directions, spends no magic, and stops when movement is released',()=>{for(const dir of [-1,1]){const g=empty();g.player.x=900;g.energy=100;const input=dir<0?{left:true,dash:true}:{right:true,dash:true};tick(g,.5,input);assert.ok(Math.abs(g.player.x-(900+dir*CFG.dashSpeed*.5))<.01);assert.equal(g.energy,100);assert.equal(g.player.dashing,true);g.step(1/120);assert.equal(g.player.vx,0);assert.equal(g.player.dashing,false);}});
test('Running fire uses the run cycle and preserves cursor-directed projectiles and leg phase',()=>{const a=empty(),b=empty();for(let i=0;i<60;i++){a.step(1/120,{right:true,dash:true});b.step(1/120,{right:true,dash:true,fire:true,aimX:1100,aimY:180});assert.equal(a.player.runPhase,b.player.runPhase);assert.equal(poseFor(b.player).running,true);assert.equal(poseFor(b.player).split,false);}assert.ok(b.bullets.length);assert.ok(b.bullets.every(x=>x.vy<0));});
test('Dash can jump, uses airborne poses and does not bypass damage or arena walls',()=>{const g=empty();g.player.x=500;g.player.inv=0;g.step(1/120,{right:true,dash:true,jump:true,jumpHeld:true});assert.ok(g.player.vy<0);assert.equal(g.player.vx,CFG.dashSpeed);assert.equal(poseFor(g.player).running,false);g.hurt(g.player.x+20);assert.equal(g.life,1);assert.equal(g.player.dashing,false);g.step(1/120,{right:true,dash:true});assert.equal(g.player.dashing,false);const w=empty();w.arenaLocked=true;w.arenaStart=300;w.player.x=300;tick(w,.5,{left:true,dash:true});assert.equal(w.player.x,300);assert.equal(w.player.runPhase,0);});

function drain(g){for(let i=0;i<300;i++){if(g.state==='encounter')tick(g,5);g.tickStory(.01);if(!g.story)break;g.story.revealed=true;g.advanceStory();}assert.equal(g.story,null);}
function tutorial(area=0){const g=new Game(42,{tutorial:true});if(area){g.area=area;g.loadTutorial();}return g;}
function room(n){const g=tutorial();g.room=n;if(n>=1){g.finishedStories.add('home-start');g.seenStories.add('home-start');g.tutorialSeen.add('moved');}if(n>=2){g.finishedStories.add('home-step');g.seenStories.add('home-step');g.tutorialSeen.add('jumped');g.tutorialSeen.add('jumpRoute');}g.loadTutorial();return g;}
test('Full script preserves surviving dialogue IDs and the requested deletions',()=>{const lines=[...CONTENT.openingLines,...CONTENT.story.flatMap(e=>e.lines),...CONTENT.farewell.lines,...CONTENT.death.lines];const ids=lines.filter(l=>l.id).map(l=>l.id);assert.equal(new Set(ids).size,53);for(let i=1;i<=60;i++)assert.equal(ids.includes('M-'+String(i).padStart(3,'0')),![10,20,27,29,30,31,45].includes(i));assert.equal(CONTENT.chapters[0].stages[0].areas.length,2);assert.equal(CONTENT.chapters[0].endingEvent,'forest-gate');});
test('Typewriter reveals Unicode characters progressively and manual advance first reveals the full line',()=>{const g=empty();g.beginStory({id:'read',lines:[{text:'魔女♥♩こんにちは'},{text:'次の行'}]});assert.equal(g.storyText(),'');g.tickStory(.1);assert.equal(g.storyText(),'魔女');g.advanceStory(true);assert.equal(g.story.index,0);assert.equal(g.storyText(),'魔女♥♩こんにちは');g.advanceStory(true);assert.equal(g.story.index,1);assert.equal(g.storyText(),'');});
test('In-play typewriter leaves movement and combat clocks running but freezes in pause',()=>{const g=empty();g.beginStory({id:'test',lines:[{text:'これは少し長い台詞です。移動しながら読むことができます。'}]});const x=g.player.x;tick(g,.3,{right:true,fire:true});assert.ok(g.player.x>x);assert.ok(g.story.elapsed>0);const elapsed=g.story.elapsed;g.state='paused';tick(g,2);assert.equal(g.story.elapsed,elapsed);});
test('Simultaneous tutorial reactions queue by priority and finish automatically without input',()=>{const g=room(2);drain(g);g.storySignals.add('hurt');g.storySignals.add('heal');g.storySignals.add('firstHit');g.tickStory(.01);assert.equal(g.story.id,'first-damage');const ids=['first-damage','first-heal','first-hit'],order=[];for(let n=0;n<120*90&&!ids.every(id=>g.finishedStories.has(id));n++){if(g.story&&!order.includes(g.story.id))order.push(g.story.id);g.step(1/120);}assert.deepEqual(order,ids);for(const id of ids)assert.ok(g.finishedStories.has(id));});
test('Optional damage, healing and revival stories do not trigger without actual signals',()=>{const g=tutorial();g.player.x=100;drain(g);for(const id of ['first-damage','first-heal','cookie-revived'])assert.equal(g.seenStories.has(id),false);g.player.inv=0;g.hurt(1000);drain(g);assert.ok(g.finishedStories.has('first-damage'));g.happiness=99;g.collectSweet(g.sweet(0,0,'candy',null));drain(g);assert.ok(g.finishedStories.has('first-heal'));});
test('Opening stays indoors, begins seated, keeps cookie/slime on plate and emits one transform effect',()=>{assert.equal(openingFrame(0).cookie,true);const f=openingFrame(OPENING.transform);assert.equal(f.slimeX+16,OPENING.plateX);assert.equal(f.slimeY+28,OPENING.plateY);assert.equal(f.transformX,prologueHand().x);assert.equal(openingFrame(OPENING.end).scene,'house');const g=tutorial();g.beginEntrance();settle(g);g.setAutoDialogue(true);for(let n=0;n<12000&&g.state==='cinematic';n++)g.step(1/120);assert.equal(g.state,'playing');assert.equal(g.area,0);assert.equal(g.player.x,297);assert.equal(g.events.filter(e=>e.type==='transform').length,1);});
test('Opening skip and natural completion give the same interior start and no lesson rewards',()=>{const a=tutorial(),b=tutorial();for(const g of[a,b]){g.beginEntrance();settle(g);}a.finishOpening();b.setAutoDialogue(true);for(let i=0;i<12000&&b.state==='cinematic';i++)b.step(1/120);assert.deepEqual(a.player,b.player);assert.equal(a.defeated,0);assert.equal(a.area,0);assert.equal(a.storySignals.has('firstRestored'),false);});
test('Furniture blocks walking but can be crossed with a normal held jump',()=>{const g=room(1);g.player.x=485;drain(g);tick(g,.4,{right:true});assert.equal(g.player.x,506);g.step(1/120,{right:true,jump:true,jumpHeld:true});tick(g,.7,{right:true,jumpHeld:true});assert.ok(g.player.x>620);});
test('First slime attacks and can be transformed and immediately eaten with starting gear',()=>{const g=room(2);drain(g);const e=g.enemies[0];g.player.x=e.x-200;for(let i=0;i<120*8&&g.defeated===0;i++){if(g.story)drain(g);const candy=e.state==='candy';g.step(1/120,{fire:!candy,aimX:e.x+16,aimY:e.y+14,right:candy&&g.player.x<e.x,left:candy&&g.player.x>e.x+10});}assert.equal(g.defeated,1);assert.equal(g.life,2);assert.ok(g.storySignals.has('firstHit'));assert.ok(g.storySignals.has('firstRestored'));assert.ok(g.storySignals.has('firstEaten'));drain(g);assert.ok(g.finishedStories.has('cookie-eaten'));});
test('An uneaten cookie revives at five seconds with full health; revival dialogue precedes first meal',()=>{const g=room(2);drain(g);const e=g.enemies[0];g.player.x=100;g.player.inv=100;g.storySignals.add('firstHit');g.transform(e,'star');assert.equal(e.sweet.kind,'cookie');drain(g);tick(g,5.1);assert.equal(e.state,'alive');assert.equal(e.hp,e.maxHp);assert.ok(g.storySignals.has('firstRevived'));g.transform(e,'star');g.collectSweet(e.sweet);const order=[];for(let i=0;i<250;i++){g.tickStory(.01);if(!g.story)break;order.push(g.story.id);g.advanceStory();}assert.ok(order.indexOf('cookie-revived')<order.indexOf('cookie-eaten'));});
test('Interior door requires first confirmed meal; area transition retains resources',()=>{const g=room(2);drain(g);g.player.x=g.exit.x;assert.equal(g.enterDoor(),false);g.storySignals.add('firstEaten');g.finishedStories.add('cookie-eaten');g.energy=37;g.life=1;g.maxLife=3;g.happiness=46;g.inventory=['star','spread'];assert.equal(g.enterDoor(),true);settle(g);assert.equal(g.area,1);assert.equal(g.chapter,0);assert.deepEqual([g.life,g.maxLife,g.happiness,g.energy,g.inventory],[1,3,46,37,['star','spread']]);assert.equal(g.enemies.length,3);assert.equal(g.events.some(e=>e.type==='tutorialComplete'),false);});
test('Backyard enemies yield different sweets and only eaten enemies count toward clearing',()=>{const g=tutorial(1),kinds=[];for(const e of g.enemies){g.transform(e,'star');kinds.push(e.sweet.kind);}assert.equal(g.gardenKills,0);assert.equal(new Set(kinds).size,3);for(const e of g.enemies)g.collectSweet(e.sweet);assert.equal(g.gardenKills,3);assert.ok(g.storySignals.has('gardenCleared'));});
test('Placed sweets trigger their own lesson and recovery is never required for the exit',()=>{const g=tutorial(1);g.gardenKills=3;g.storySignals.add('gardenCleared');g.player.x=2100;g.collectSweet(g.sweets.find(s=>s.placedLesson));drain(g);assert.ok(g.finishedStories.has('placed-eaten'));assert.equal(g.storySignals.has('heal'),false);assert.equal(g.inventory.length,1);g.player.x=g.exit.x;assert.equal(g.enterDoor(),true);settle(g);assert.equal(g.area,2);assert.equal(g.enemies.length,0);});
test('The forest gate loads directly as a skippable event with no playable frame',()=>{const g=tutorial(1);g.gardenKills=3;g.storySignals.add('placedEaten');g.finishedStories.add('placed-eaten');g.player.x=g.exit.x;assert.equal(g.enterDoor(),true);settle(g);assert.equal(g.area,2);assert.equal(g.state,'event');assert.equal(g.story.id,'departure');assert.equal(g.story.lines[0].id,'M-046');const x=g.player.x,time=g.time;tick(g,10,{right:true,fire:true,jump:true});assert.equal(g.player.x,x);assert.equal(g.time,time);assert.equal(g.bullets.length,0);g.advanceStory();assert.equal(g.events.filter(e=>e.type==='rustle').length,1);g.skipStory();assert.equal(g.state,'transition');settle(g);assert.equal(g.chapter,1);assert.deepEqual([g.life,g.maxLife,g.happiness,g.inventory],[2,2,0,['star']]);assert.ok(g.events.some(e=>e.type==='tutorialComplete'));});
test('Completing departure walks fully off screen before fading; skipping resets resources identically',()=>{const a=tutorial(2),b=tutorial(2);for(const g of[a,b]){g.life=1;g.maxLife=4;g.happiness=99;g.inventory=['comet','sugar'];g.energy=3;}a.skipStory();settle(a);drain(b);assert.equal(b.state,'leaving');assert.equal(b.chapter,0);const x=b.player.x;tick(b,1,{left:true,fire:true,jump:true});assert.ok(b.player.x>x);assert.equal(b.player.vx,112);assert.equal(b.camera,0);assert.equal(b.bullets.length,0);while(b.state==='leaving'&&b.player.x<1056)b.step(1/120);assert.equal(b.state,'leaving');assert.ok(b.player.x>CFG.width+45);assert.equal(b.chapter,0);tick(b,1.05);assert.equal(b.state,'transition');assert.equal(b.transition.covered,true);settle(b);assert.equal(b.chapter,1);assert.deepEqual([b.life,b.maxLife,b.happiness,b.energy,b.inventory],[a.life,a.maxLife,a.happiness,a.energy,a.inventory]);});
test('Tutorial death shows M-060 once before the dedicated game-over state',()=>{const g=tutorial();g.life=1;g.player.inv=0;g.hurt(1000);assert.equal(g.state,'event');assert.equal(g.story.lines[0].id,'M-060');tick(g,5);assert.equal(g.state,'lost');assert.equal(g.events.filter(e=>e.type==='lost').length,1);const retry=tutorial();assert.equal(retry.area,0);assert.equal(retry.life,2);assert.equal(retry.happiness,0);});
test('Chapter one starts directly when tutorial is skipped and has unchanged three-stage content',()=>{const g=new Game(5);assert.equal(g.chapter,1);assert.equal(g.area,0);assert.equal(CONTENT.chapters[1].stages.length,3);assert.equal(g.storyQueue.length,0);});
test('Cookie reaching stays seated until the surprise, then preserves the standing reaction',()=>{for(const t of [0,4.9,5,8,12,18.39])assert.equal(openingFrame(t).seated,true);for(const t of [18.4,20,25])assert.equal(openingFrame(t).seated,false);assert.equal(openingFrame(8).pose,1);assert.equal(openingFrame(18.4).pose,3);});
test('Movement and jump rooms contain no combat targets, even when shooting and dashing ahead',()=>{for(const n of [0,1]){const g=room(n);tick(g,10,{right:true,dash:true,fire:true,jumpHeld:true});assert.equal(g.room,n);assert.equal(g.enemies.length,0);assert.equal(g.defeated,0);for(const signal of ['firstHit','firstRestored','firstEaten'])assert.equal(g.storySignals.has(signal),false);assert.equal(g.seenStories.has('first-encounter'),false);}});
test('Each room door waits for its own lesson and arrives with no old bullets or dialogue',()=>{const g=room(0);g.player.x=g.exit.x;assert.equal(g.enterDoor(),false);drain(g);assert.equal(g.enterDoor(),false);g.step(1/120);g.shoot();assert.ok(g.bullets.length);assert.equal(g.enterDoor(),true);settle(g);assert.equal(g.area,0);assert.equal(g.room,1);assert.equal(g.bullets.length,0);assert.equal(g.story,null);g.player.x=g.exit.x;drain(g);assert.equal(g.enterDoor(),false);g.tutorialSeen.add('jumped');g.step(1/120);assert.ok(g.tutorialSeen.has('jumpRoute'));assert.equal(g.enterDoor(),true);settle(g);assert.equal(g.room,2);assert.equal(g.enemies.length,1);g.step(1/120);assert.equal(g.story.id,'first-encounter');assert.equal(g.story.lines[g.story.index].text,'いた！');assert.equal(g.storyQueue.length,0);});
test('The complete storeroom route can be crossed with normal jumps and records lesson completion',()=>{const g=room(1);let jumps=0;for(let i=0;i<1800&&g.player.x<1500;i++){if(g.story)drain(g);const ahead=g.platforms.some(p=>p.solid&&p.x-(g.player.x+g.player.w)<85&&p.x>=g.player.x+g.player.w);const jump=g.player.grounded&&ahead;if(jump)jumps++;g.step(1/120,{right:true,jump,jumpHeld:true});}assert.ok(g.player.x>=1500);assert.ok(jumps>=3);tick(g,1);assert.ok(g.tutorialSeen.has('jumpRoute'));assert.equal(g.enemies.length,0);});
test('Tutorial messages freeze every gameplay clock and all player actions while visible',()=>{for(const wand of Object.keys(WANDS)){const g=room(2);g.inventory=[wand,'star'];g.player.x=550;g.shoot();g.enemyShot(700,400,500,420,200);g.energy=37;g.storySignals.add('firstHit');g.transform(g.enemies[0],'star');g.tickStory(.01);const snap=()=>({time:g.time,energy:g.energy,player:{...g.player},enemy:g.enemies.map(e=>[e.x,e.y,e.hp,e.state,e.candyTime,e.t,e.attack]),sweets:g.sweets.map(e=>[e.x,e.y,e.age]),particles:g.particles.map(e=>[e.x,e.y,e.t]),bullets:g.bullets.map(b=>[b.x,b.y,b.life]),hostile:g.hostile.map(b=>[b.x,b.y,b.life]),slot:g.slot,inventory:[...g.inventory]});const before=structuredClone(snap());tick(g,1,{right:true,dash:true,jump:true,fire:true});g.switchWand();g.interact();assert.equal(g.shoot(),false);assert.deepEqual(snap(),before);assert.equal(g.story.index,0);assert.equal(g.storyText(),g.story.lines[0].text);drain(g);assert.equal(g.messagePaused(),false);assert.equal(g.enemies[0].candyTime,5);tick(g,.5);assert.ok(g.enemies[0].candyTime<4.51);}});
test('Discovery room has no barrier, and movement and shooting resume only after the introduction',()=>{const g=room(2);assert.equal(g.platforms.some(p=>!p.ground),false);g.step(1/120);assert.equal(g.story.id,'first-encounter');const x=g.player.x;g.advanceStory(true);tick(g,1,{right:true,fire:true});assert.equal(g.player.x,x);drain(g);g.player.x=300;for(let n=0;n<120&&!g.storySignals.has('firstHit');n++)g.step(1/120,{right:true,fire:true,aimX:g.enemies[0].x+16,aimY:g.enemies[0].y+14});assert.ok(g.player.x>300);assert.ok(g.storySignals.has('firstHit'));});
test('The escaping slime disappears inside the storage doorway, never beyond the screen',()=>{let previous=0;for(let t=OPENING.escape;t<OPENING.end;t+=.01){const f=openingFrame(t);assert.ok(f.slimeX>=previous);assert.ok(f.slimeX+32<=878);assert.ok(f.slimeX+32<CFG.width);previous=f.slimeX;if(f.slimeAlpha<1&&f.monster)assert.ok(f.slimeX>=806&&f.slimeX+32<=878);}assert.equal(openingFrame(35.5).monster,false);assert.ok(Math.abs(openingFrame(34.9).slimeX+16-842)<1e-8);});
test('Opening click first reveals its line, then ends that line without skipping the next animation beat',()=>{const g=tutorial();g.state='cinematic';g.cinematic={t:5.05};g.advanceOpening();assert.equal(g.cinematic.revealId,'M-002');assert.equal(g.cinematic.t,5.05);g.advanceOpening();assert.equal(g.cinematic.t,9.8);assert.equal(openingFrame(10.2).cookie,true);assert.notEqual(openingFrame(10.2).cookieX,OPENING.plateX-11);});
test('Removed lines stay absent and the backyard begins with the requested exclamation',()=>{const lines=[...CONTENT.story.flatMap(e=>e.lines),...CONTENT.farewell.lines];for(const id of ['M-027','M-029','M-030','M-031'])assert.equal(lines.some(l=>l.id===id),false);assert.equal(CONTENT.story.find(e=>e.id==='garden-arrival').lines[0].text,'はぁ!?　なんでこんなに魔物がいるのよ！');assert.equal(CONTENT.farewell.lines.at(-1).id,'M-059');});
test('Departure walk pauses and can be skipped without ever returning control to the gate',()=>{const g=tutorial(2);drain(g);const x=g.player.x;g.state='paused';tick(g,3);assert.equal(g.player.x,x);g.state='leaving';g.skipDeparture();assert.equal(g.state,'transition');settle(g);assert.equal(g.chapter,1);});

test('Stage arrivals are opaque, while actual damage retains its independent blink timer',()=>{const g=new Game(9);for(let stage=0;stage<3;stage++){g.stage=stage;g.player.damageBlink=1;g.loadStage();assert.equal(g.player.damageBlink,0);assert.equal(g.player.inv,1.5);}for(let n=0;n<3;n++){const g=room(n);assert.equal(g.player.damageBlink,0);}const a=empty();a.player.inv=0;a.hurt(400);assert.equal(a.player.damageBlink,CFG.invincible);tick(a,.5);assert.ok(a.player.damageBlink<1.01&&a.player.damageBlink>.99);});
test('The first slime introduction separates discovery, approach, dodge, and the magic lesson',()=>{const g=room(2);g.step(1/120);assert.deepEqual(g.story.lines.map(l=>l.id),['M-012','M-013']);g.advanceStory();g.advanceStory();assert.equal(g.state,'encounter');assert.equal(g.story,null);const t=g.time,life=g.life,energy=g.energy;tick(g,.6,{fire:true,right:true,jump:true});assert.ok(g.player.x>85&&g.player.x<480);assert.ok(poseFor(g.player).base>=4);const d=g.encounter;while(d.t<d.walkTime+.6)g.step(1/120);assert.ok(g.player.x<480);assert.ok(g.player.y<402);assert.ok(g.enemies[0].y<430);assert.equal(g.story,null);while(g.state==='encounter')g.step(1/120,{fire:true});assert.deepEqual([g.time,g.life,g.energy],[t,life,energy]);assert.equal(g.bullets.length,0);assert.equal(g.story.id,'first-defense');assert.equal(g.story.lines[0].id,'M-014');assert.equal(g.enemies[0].hp,4);assert.equal(g.player.damageBlink,0);drain(g);assert.ok(g.finishedStories.has('first-defense'));const x=g.player.x;g.step(1/120,{left:true});assert.ok(g.player.x<x);});
test('The dodge scene pauses, skips into the same reaction, and does not repeat during combat',()=>{const a=room(2),b=room(2);for(const g of[a,b]){g.step(1/120);g.advanceStory();g.advanceStory();}a.state='paused';const x=a.player.x,t=a.encounter.t;tick(a,4);assert.equal(a.player.x,x);assert.equal(a.encounter.t,t);a.state='encounter';a.finishEncounter();tick(b,4);for(const g of[a,b]){assert.equal(g.state,'playing');assert.equal(g.story.id,'first-defense');assert.equal(g.player.x,335);assert.equal(g.enemies[0].x,480);drain(g);tick(g,.1);assert.equal(g.encounter,null);assert.equal(g.story,null);}});
test('Every wand turns the boss into a huge cake with a centered, floor-aligned hitbox',()=>{for(const wand of Object.keys(WANDS)){const g=arena(),e=g.enemies[0],cx=e.x+e.w/2,bottom=e.y+e.h;g.transform(e,wand);assert.equal(e.sweet.kind,'cake');assert.equal(e.sweet.scale,4);assert.equal(e.sweet.w,88);assert.equal(e.sweet.h,96);assert.equal(e.sweet.x+e.sweet.w/2,cx);assert.equal(e.sweet.y+e.sweet.h,bottom);assert.equal(g.hitStop,BOSS.hitStop);assert.equal(g.defeated,0);}});
test('Fatal boss projectile stops all gameplay immediately, including contact eating, then resumes',()=>{const g=arena(),e=g.enemies[0];e.hp=1;g.player.inv=5;g.player.x=e.x;g.energy=23;g.bullets=[{x:e.x,y:e.y,w:12,h:10,vx:0,vy:0,life:1,damage:1,wand:'star',hits:new Set()}];g.step(1/120);assert.equal(e.state,'candy');assert.equal(g.state,'playing');assert.equal(g.eaten,0);assert.equal(e.candyTime,5);assert.equal(g.bullets.length,0);const snapshot=()=>JSON.stringify({time:g.time,p:g.player,energy:g.energy,particles:g.particles,age:e.sweet.age,candy:e.candyTime});const before=snapshot();tick(g,.1,{right:true,fire:true,jump:true});g.collectSweet(e.sweet);assert.equal(g.shoot(),false);assert.equal(g.hurt(9999),false);assert.equal(snapshot(),before);g.state='paused';const stop=g.hitStop;tick(g,2);assert.equal(g.hitStop,stop);g.state='playing';tick(g,BOSS.hitStop-.1+.02);if(g.state==='celebrating')tick(g,3.2);assert.equal(g.state,'won');assert.equal(g.eaten,1);});
test('A huge cake has five full gameplay seconds after hitstop and revives without shifting the boss',()=>{const g=arena(),e=g.enemies[0],x=e.x;g.player.x=g.arenaStart+20;g.transform(e,'star');tick(g,BOSS.hitStop);assert.equal(e.candyTime,5);tick(g,4.9);assert.equal(e.state,'candy');tick(g,.11);assert.equal(e.state,'alive');assert.equal(e.hp,e.maxHp);assert.ok(Math.abs(e.x-x)<.01);assert.equal(g.sweets.length,0);});
test('Normal monsters transform without hitstop or a size change',()=>{const g=empty(),e=g.spawnEnemy('slime',600,458);g.transform(e,'star');assert.equal(g.hitStop,0);assert.equal(e.sweet.w,22);assert.equal(e.sweet.h,20);});

test('Boss meal celebrates before the clear screen and pause freezes the celebration',()=>{const g=arena(),b=g.enemies[0];g.transform(b,'star');tick(g,.51);g.collectSweet(b.sweet);assert.equal(g.state,'celebrating');assert.equal(g.events.some(e=>e.type==='won'),false);const life=g.life,time=g.time;tick(g,.9,{fire:true,right:true});assert.ok(g.player.y<402);assert.equal(g.time,time);assert.equal(g.life,life);const t=g.celebration.t;g.state='paused';tick(g,4);assert.equal(g.celebration.t,t);g.state='celebrating';tick(g,2.3);assert.equal(g.state,'won');assert.equal(g.events.filter(e=>e.type==='won').length,1);});
test('AUTO waits for all characters, then grants a separate reading interval',()=>{const g=empty();g.setAutoDialogue(true);g.beginStory({id:'auto',blocking:true,lines:[{text:'0123456789012345678901'},{text:'次'}]});tick(g,.9);assert.equal(g.story.index,0);assert.ok(g.storyText().length<22);tick(g,.2);assert.equal(g.storyText().length,22);tick(g,2);assert.equal(g.story.index,0);tick(g,.5);assert.equal(g.story.index,1);assert.equal(g.time,0);});
test('AUTO off holds indefinitely; turning on starts a fresh reading interval',()=>{const g=empty();g.beginStory({id:'a',blocking:true,lines:[{text:'こんにちは'},{text:'続き'}]});tick(g,20);assert.equal(g.story.index,0);g.setAutoDialogue(true);tick(g,1);assert.equal(g.story.index,0);g.setAutoDialogue(false);tick(g,20);assert.equal(g.story.index,0);g.setAutoDialogue(true);tick(g,1.8);assert.equal(g.story.index,1);});
test('Manual reveal resets the AUTO reading clock, manual next remains available',()=>{const g=empty();g.setAutoDialogue(true);g.beginStory({id:'a',lines:[{text:'文字送りの途中で全文を表示するテストです。'},{text:'次へ'}]});tick(g,.1);g.advanceStory(true);assert.equal(g.story.readElapsed,0);tick(g,.5);assert.equal(g.story.index,0);g.advanceStory(true);assert.equal(g.story.index,1);});
test('Pause freezes typewriter, AUTO reading time and event animation together',()=>{const g=empty();g.setAutoDialogue(true);g.beginStory({...CONTENT.chapterOne.find(e=>e.id==='c1-hauling')});tick(g,.3);const before=[g.story.elapsed,g.story.readElapsed,g.storyScene.t,g.time];g.state='paused';tick(g,30);assert.deepEqual([g.story.elapsed,g.story.readElapsed,g.storyScene.t,g.time],before);});
test('Opening manual holds its line, AUTO resumes and chapter reset preserves the choice',()=>{const g=tutorial();g.state='cinematic';g.cinematic={t:.4};tick(g,20);assert.equal(g.openingCurrent().id,'M-001');assert.equal(g.openingText(),CONTENT.openingLines[0].text);assert.equal(g.time,0);g.setAutoDialogue(true);tick(g,4);assert.equal(g.openingCurrent().id,'M-002');g.reset(9);assert.equal(g.autoDialogue,true);});
test('An airborne boss meal keeps vertical momentum and waits for real floor contact',()=>{for(const vy of [-240,180]){const g=arena(),b=g.enemies[0];g.transform(b,'star');tick(g,.51);g.player.y=250;g.player.vy=vy;g.player.grounded=false;const before=g.time;g.collectSweet(b.sweet);assert.equal(g.state,'victoryLanding');assert.equal(g.player.vy,vy);assert.equal(g.celebration,null);tick(g,.1,{fire:true,right:true});assert.equal(g.state,'victoryLanding');assert.equal(g.time,before);for(let n=0;n<500&&g.state==='victoryLanding';n++)g.step(1/120);assert.equal(g.state,'celebrating');assert.equal(g.celebration.y,402);assert.equal(g.celebration.t,0);assert.equal(g.player.y,402);tick(g,3.2);assert.equal(g.state,'won');}});
test('Victory landing respects upper platforms and pause, never starts the pose in midair',()=>{const g=arena(),b=g.enemies[0];g.transform(b,'star');tick(g,.51);g.platforms.unshift({x:g.player.x-30,y:330,w:120,h:16});Object.assign(g.player,{y:240,vy:50,grounded:false});g.collectSweet(b.sweet);const y=g.player.y;g.state='paused';tick(g,3);assert.equal(g.player.y,y);g.state='victoryLanding';for(let n=0;n<300&&g.state==='victoryLanding';n++)g.step(1/120);assert.equal(g.celebration.y,274);});
function chapter1(stage=0){const g=new Game(4);g.stage=stage;g.loadStage();g.enemies=g.enemies.filter(e=>e.type==='boss');g.sweets=[];g.drops=[];g.player.inv=10000;return g;}
function readC1(g){for(let n=0;n<500;n++){g.tickStory(.05);if(g.story)g.advanceStory(true);}}
test('Chapter 1 covers all 63 unique script IDs and exposes no later-chapter secrets',()=>{const lines=CONTENT.chapterOne.flatMap(e=>e.lines);assert.equal(lines.length,63);assert.equal(new Set(lines.map(l=>l.id)).size,63);for(let i=1;i<=63;i++)assert.ok(lines.some(l=>l.id==='C1-M'+String(i).padStart(3,'0')));assert.ok(!lines.some(l=>/グラトニア|封印|黒幕|ライバル/.test(l.text)));});
test('Chapter 1 route remains ordered even after rushing to the forest exit',()=>{const g=chapter1();g.player.x=g.exit.x;assert.equal(g.canEnterDoor(),true);g.tickStory(0);assert.equal(g.story.id,'c1-woods');readC1(g);for(const id of ['c1-woods','c1-sight','c1-trail','c1-hauling'])assert.ok(g.finishedStories.has(id));assert.equal(g.canEnterDoor(),true);g.enterDoor();settle(g);assert.equal(g.stage,1);assert.equal(g.story,null);assert.equal(g.storyQueue.length,0);});
test('Garden clues lead to castle, without requiring optional eating or damage',()=>{const g=chapter1(1);g.player.x=g.exit.x;readC1(g);for(const id of ['c1-garden','c1-carrier','c1-stock','c1-castle-path'])assert.ok(g.finishedStories.has(id));assert.equal(g.finishedStories.has('c1-hurt'),false);assert.equal(g.canEnterDoor(),true);g.enterDoor();settle(g);assert.equal(g.stage,2);});
test('Ordinary chapter dialogue allows movement, spells and clear time',()=>{const g=chapter1();g.player.x=110;g.step(1/120);const x=g.player.x,t=g.time;tick(g,.3,{right:true,fire:true});assert.ok(g.player.x>x);assert.ok(g.time>t);assert.ok(g.bullets.length);assert.equal(g.state,'playing');assert.equal(g.story.id,'c1-woods');});
test('Blocking chapter scenes stop timer, enemies, energy and projectiles while their actors animate',()=>{const g=chapter1();g.beginStory(g.chapterEvent('c1-hauling'));g.energy=35;const x=g.player.x,t=g.time;tick(g,2,{right:true,fire:true});assert.equal(g.time,t);assert.equal(g.energy,35);assert.equal(g.player.x,x);assert.equal(g.bullets.length,0);assert.ok(g.storyScene.t>1.9);assert.equal(g.state,'event');g.skipStory();assert.equal(g.state,'playing');});
test('Boss remains dormant until introduction finishes or is skipped',()=>{const g=chapter1(2);g.player.x=2200;g.finishedStories.add('c1-castle');g.seenStories.add('c1-castle');g.finishedStories.add('c1-storehouse');g.seenStories.add('c1-storehouse');g.step(1/120);assert.equal(g.story.id,'c1-king');assert.equal(g.bossAwake,false);const t=g.time,b=g.enemies[0],phase=b.phaseTime;tick(g,6);assert.equal(g.time,t);assert.equal(b.phaseTime,phase);g.skipStory();assert.equal(g.bossAwake,true);assert.equal(g.arenaLocked,true);tick(g,2);assert.ok(g.time>t);assert.ok(g.storySignals.has('bossWave'));});
test('Expired reactions are discarded, low-life takes precedence over the generic hurt line',()=>{const g=chapter1();g.emit('hurt');g.life=1;g.emit('lowLife');g.tickStory(0);assert.equal(g.story.id,'c1-low-life');g.skipStory();g.time+=5;g.tickStory(.5);assert.equal(g.story,null);assert.equal(g.storyQueue.length,0);});
test('Cake and revival reactions follow actual boss state and never suspend its five-second expiry',()=>{const g=chapter1(2),b=g.enemies[0];g.transform(b,'star');g.step(BOSS.hitStop);tick(g,.51);assert.equal(g.story.id,'c1-cake');assert.equal(g.state,'playing');assert.ok(b.candyTime<5);g.skipStory();tick(g,5);assert.equal(b.state,'alive');assert.equal(g.story.id,'c1-revived');});
test('Boss meal lands, celebrates, plays the ending and fades to exactly one clear',()=>{const g=chapter1(2),b=g.enemies[0];g.transform(b,'star');tick(g,.51);Object.assign(g.player,{y:300,vy:80,grounded:false});g.collectSweet(b.sweet);const t=g.time;assert.equal(g.story,null);for(let i=0;i<300&&g.state==='victoryLanding';i++)g.step(1/120);assert.equal(g.story.id,'c1-feast');assert.equal(g.celebration.t,0);tick(g,4);assert.equal(g.state,'celebrating');assert.equal(g.time,t);g.skipStory();g.step(1/120);assert.equal(g.state,'event');assert.equal(g.story.id,'c1-ending');tick(g,2);assert.equal(g.time,t);g.skipStory();assert.equal(g.state,'chapterClear');tick(g,.8);assert.equal(g.state,'won');assert.equal(g.time,t);assert.equal(g.events.filter(e=>e.type==='won').length,1);});
test('Automatic chapter-one ending completes at its clear screen',()=>{const g=chapter1(2),b=g.enemies[0];g.setAutoDialogue(true);g.transform(b,'star');tick(g,.51);g.collectSweet(b.sweet);for(let n=0;n<120*150&&g.state!=='won';n++)g.step(1/120);assert.equal(g.state,'won');assert.equal(g.chapter,1);assert.equal(g.stage,2);assert.ok(g.finishedStories.has('c1-feast'));assert.ok(g.finishedStories.has('c1-ending'));});
test('Chapter death immediately ends play and preserves its line for the result screen',()=>{const g=chapter1();g.life=1;g.player.inv=0;g.hurt(500);assert.equal(g.state,'lost');assert.equal(g.story,null);assert.equal(g.deathMessage.id,'C1-M063');const t=g.time;tick(g,5);assert.equal(g.state,'lost');assert.equal(g.time,t);assert.equal(g.events.filter(e=>e.type==='lost').length,1);});
test('A heart fills exactly the newly added capacity, preserving existing missing health and happiness',()=>{for(const [life,maxLife,expectedLife,expectedMax] of [[2,2,3,3],[1,2,2,3],[1,3,2,4],[1,4,1,4],[4,4,4,4]]){const g=empty();g.life=life;g.maxLife=maxLife;g.happiness=99;g.drops=[{type:'heart',x:g.player.x,y:428,cooldown:0}];g.interact();assert.equal(g.life,expectedLife);assert.equal(g.maxLife,expectedMax);assert.equal(g.happiness,99);assert.equal(g.storySignals.has('heal'),false);assert.equal(g.drops.length,0);g.interact();assert.equal(g.life,expectedLife);}});
test('Fatal damage interrupts live dialogue, clears both bullet lists and settles shake before defeat',()=>{for(const auto of [false,true])for(const chapter of [0,1]){const g=chapter===0?tutorial():chapter1();g.setAutoDialogue(auto);g.player.x=110;g.tickStory(.01);g.life=1;g.player.inv=0;g.bullets.push({x:0,y:0});g.enemyShot(100,400,200,400,100);g.hurt(300);assert.equal(g.life,0);assert.equal(g.state,chapter===0?'event':'lost');if(chapter===0)assert.equal(g.story.id,'tutorial-death');else assert.equal(g.deathMessage.id,'C1-M063');assert.equal(g.bullets.length,0);assert.equal(g.hostile.length,0);const t=g.time;tick(g,.3);assert.equal(g.shake,0);tick(g,5);assert.equal(g.state,'lost');assert.equal(g.time,t);assert.equal(g.story,null);assert.equal(g.events.filter(e=>e.type==='lost').length,1);g.reset(8,{tutorial:chapter===0});assert.equal(g.life,2);assert.equal(g.defeat,null);assert.equal(g.shake,0);}});
test('Death cannot hang if its dialogue is cancelled, stalled or switched to manual',()=>{for(const mode of ['removed','manual','stalled']){const g=tutorial();g.life=1;g.player.inv=0;g.hurt(300);if(mode==='removed')g.story=null;if(mode==='manual')g.story.auto=false;if(mode==='stalled')g.story.minScene=100;tick(g,5.1);assert.equal(g.state,'lost');assert.equal(g.shake,0);assert.equal(g.events.filter(e=>e.type==='lost').length,1);tick(g,5);assert.equal(g.events.filter(e=>e.type==='lost').length,1);}});
test('Tutorial death presentation pauses and skips without residual shake',()=>{const g=tutorial();g.life=1;g.player.inv=0;g.hurt(300);tick(g,.1);const elapsed=g.defeat.elapsed;g.state='paused';tick(g,10);assert.equal(g.defeat.elapsed,elapsed);g.state='event';g.skipStory();assert.equal(g.state,'lost');assert.equal(g.shake,0);assert.equal(g.defeat,null);g.finishDefeat();assert.equal(g.events.filter(e=>e.type==='lost').length,1);});
test('Fatal contact and projectiles end every Chapter 1 stage in the same frame, with either AUTO setting',()=>{for(const stage of [0,1,2])for(const auto of [false,true])for(const source of ['contact','projectile']){const g=chapter1(stage);g.enemies=[];g.player.x=120;g.setAutoDialogue(auto);g.tickStory(0);g.life=1;g.player.inv=0;g.storyQueue.push({...g.chapterEvent('c1-hurt')});if(source==='contact'){const e=g.spawnEnemy('slime',g.player.x,CFG.ground);e.vx=0;e.attack=100;}else g.enemyShot(g.player.x,g.player.y+20,g.player.x+1,g.player.y+20,0);g.step(1/120);assert.equal(g.state,'lost',stage+' '+auto+' '+source);assert.equal(g.life,0);assert.equal(g.story,null);assert.equal(g.storyQueue.length,0);assert.equal(g.shake,0);assert.equal(g.defeat,null);assert.equal(g.deathMessage.id,'C1-M063');assert.equal(g.events.filter(e=>e.type==='lost').length,1);}});
test('Zero health cannot remain trapped in a playing, dialogue or swap state',()=>{for(const state of ['playing','event','swap']){const g=chapter1();g.life=0;g.state=state;g.story={...g.chapterEvent('c1-death'),auto:false,index:0,elapsed:0,readElapsed:0};g.step(1/120);assert.equal(g.state,'lost');assert.equal(g.story,null);assert.equal(g.shake,0);}});
test('Restart clears the death line, pending dialogue and terminal state on repeated deaths',()=>{const g=chapter1();for(let n=0;n<5;n++){g.life=1;g.player.inv=0;g.hurt(900);assert.equal(g.state,'lost');g.reset(n);assert.equal(g.life,2);assert.equal(g.state,'playing');assert.equal(g.deathMessage,null);assert.equal(g.defeat,null);assert.equal(g.storyQueue.length,0);g.step(1/120,{right:true});assert.ok(g.player.x>85);}});

test('Space at a Chapter 1 exit skips unread and queued dialogue and carries resources',()=>{for(const stage of [0,1])for(const auto of [false,true]){const g=chapter1(stage);g.setAutoDialogue(auto);g.player.x=g.exit.x;g.life=1;g.maxLife=3;g.happiness=79;g.energy=37;g.inventory=['spread','sugar'];g.tickStory(0);g.storyQueue.push({...g.chapterEvent(stage===0?'c1-trail':'c1-stock'),index:0});const active=g.story.id,queued=g.storyQueue.map(e=>e.id),time=g.time;assert.ok(g.story);assert.ok(queued.length);assert.equal(g.canEnterDoor(),true);g.step(1/120,controlsFor(new Set(['Space']),new Set(['Space']),g.canEnterDoor()));assert.equal(g.state,'transition');assert.equal(g.story,null);assert.equal(g.storyQueue.length,0);assert.ok(g.finishedStories.has(active));for(const id of queued)assert.ok(g.finishedStories.has(id));assert.equal(g.time,time);settle(g);assert.equal(g.stage,stage+1);assert.deepEqual([g.life,g.maxLife,g.happiness,g.energy,g.inventory],[1,3,79,37,['spread','sugar']]);assert.equal(g.story,null);assert.equal(g.storyQueue.length,0);g.step(1/120);assert.ok(!g.story||g.story.stage===stage+2);}});
test('Space leaves a blocked event at the exit before the dialogue clock advances',()=>{const g=chapter1();g.player.x=g.exit.x;g.beginStory(g.chapterEvent('c1-hauling'));const time=g.time;assert.equal(g.state,'event');assert.equal(g.messagePaused(),true);assert.equal(g.canEnterDoor(),true);g.step(1/120,{enter:true});assert.equal(g.state,'transition');assert.equal(g.storyScene,null);assert.equal(g.story,null);assert.ok(g.finishedStories.has('c1-hauling'));assert.equal(g.time,time);settle(g);assert.equal(g.stage,1);});
test('Every tutorial room can skip its messages at the exit after the required action',()=>{for(const n of [0,1,2,3]){const g=n===3?tutorial(1):room(n);g.player.x=g.exit.x;const event=CONTENT.story.find(e=>e.id===['home-start','home-step','cookie-eaten','placed-eaten'][n]);if(n===0)g.tutorialSeen.add('moved');if(n===1)g.tutorialSeen.add('jumpRoute');if(n===2)g.storySignals.add('firstEaten');if(n===3){g.gardenKills=3;g.storySignals.add('placedEaten');}g.beginStory(event);assert.ok(g.messagePaused());assert.equal(g.canEnterDoor(),true);g.step(1/120,{enter:true});assert.equal(g.state,'transition');assert.ok(g.finishedStories.has(event.id));assert.equal(g.story,null);settle(g);if(n<2)assert.equal(g.room,n+1);else assert.equal(g.area,n===2?1:2);}});
test('Skipping messages cannot bypass required tutorial combat or placed sweets',()=>{for(const n of [0,1,2,3]){const g=n===3?tutorial(1):room(n);g.player.x=g.exit.x;if(n===3)g.gardenKills=3;g.beginStory({id:'unfinished-lesson',lines:[{text:'未達成'}]});assert.equal(g.canEnterDoor(),false);assert.equal(g.enterDoor(),false);assert.equal(g.story.id,'unfinished-lesson');assert.equal(g.finishedStories.has('unfinished-lesson'),false);}});
test('Door skipping cannot act remotely, airborne, during pause, death or boss victory',()=>{for(const mode of ['distant','airborne','raised','paused','lost','zero-life','hitstop','boss','celebrating']){const g=chapter1();g.player.x=g.exit.x;g.beginStory(g.chapterEvent('c1-hauling'));if(mode==='distant')g.player.x-=150;if(mode==='airborne')g.player.grounded=false;if(mode==='raised')g.player.y-=70;if(mode==='paused')g.state='paused';if(mode==='lost')g.state='lost';if(mode==='zero-life')g.life=0;if(mode==='hitstop')g.hitStop=.5;if(mode==='boss')g.stage=2;if(mode==='celebrating')g.state='celebrating';assert.equal(g.canEnterDoor(),false,mode);assert.equal(g.enterDoor(),false,mode);assert.equal(g.story.id,'c1-hauling',mode);}});
test('A blocked message away from an exit ignores Space and keeps time frozen',()=>{const g=chapter1();g.beginStory(g.chapterEvent('c1-hauling'));const time=g.time,x=g.player.x;g.step(1/120,controlsFor(new Set(['Space']),new Set(['Space']),g.canEnterDoor()));assert.equal(g.state,'event');assert.equal(g.story.id,'c1-hauling');assert.equal(g.story.index,0);assert.equal(g.player.x,x);assert.equal(g.time,time);});

test('Stage dialogue always waits for full text and reading time, even with saved AUTO off',()=>{for(const tutorial of [false,true])for(const auto of [false,true]){const g=new Game(1,{tutorial,story:false,autoDialogue:auto});g.enemies=[];g.sweets=[];g.seenStories=new Set(CONTENT.story.map(e=>e.id));g.beginStory({id:'stage-auto',blocking:false,auto:false,lines:[{text:'0123456789012345678901'},{text:'次'}]});assert.equal(g.stageDialogue(),true);tick(g,.9);assert.equal(g.story.index,0);assert.ok(g.storyText().length<22);tick(g,.2);assert.equal(g.storyText().length,22);tick(g,2);assert.equal(g.story.index,0);tick(g,.5);assert.equal(g.story.index,1);tick(g,2);assert.equal(g.story,null);assert.ok(g.finishedStories.has('stage-auto'));assert.equal(g.autoDialogue,auto);}});
test('Pause freezes automatic stage dialogue; resume preserves its remaining read time',()=>{const g=empty();g.beginStory({id:'stage-pause',lines:[{text:'一つ目の台詞'},{text:'二つ目'}]});tick(g,1);const elapsed=g.story.elapsed,read=g.story.readElapsed;g.state='paused';tick(g,30);assert.equal(g.story.elapsed,elapsed);assert.equal(g.story.readElapsed,read);g.state='playing';tick(g,.5);assert.equal(g.story.index,0);tick(g,1.2);assert.equal(g.story.index,1);});
test('Stage auto advance keeps gameplay running and leaves scene AUTO preferences untouched',()=>{const g=empty();g.beginStory({id:'stage',lines:[{text:'短い台詞'}]});tick(g,2.5,{right:true,fire:true});assert.equal(g.story,null);assert.ok(g.player.x>300);assert.ok(g.time>2);assert.ok(g.energy<100);assert.equal(g.autoDialogue,false);g.beginStory({id:'scene',blocking:true,lines:[{text:'イベント'}]});assert.equal(g.stageDialogue(),false);tick(g,20);assert.equal(g.story.id,'scene');g.setAutoDialogue(true);tick(g,2);assert.equal(g.story,null);});
